type SchedulerLike = { yield?: () => Promise<void> };

const yieldToMain = async (): Promise<void> => {
  const browserScheduler = (globalThis as typeof globalThis & {
    scheduler?: SchedulerLike;
  }).scheduler;

  if (browserScheduler?.yield) {
    await browserScheduler.yield();
    return;
  }

  await new Promise<void>((resolve) => setTimeout(resolve, 0));
};

export async function processCooperatively<T>(
  items: readonly T[],
  processItem: (item: T) => void,
  signal: AbortSignal,
  budgetMs = 8
): Promise<void> {
  let index = 0;

  while (index < items.length) {
    signal.throwIfAborted();
    const deadline = performance.now() + budgetMs;

    do {
      processItem(items[index]);
      index += 1;
    } while (index < items.length && performance.now() < deadline);

    if (index < items.length) await yieldToMain();
  }
}

