export function createServices(config: AppConfig) {
  const api = createApiClient({ baseUrl: config.apiBaseUrl });
  const auth = createAuthService({ api });
  return { api, auth, flags: config.flags };
}

// bootstrap.ts — composition root sở hữu timeout/fallback
export async function bootstrap() {
  const timeout = AbortSignal.timeout(5_000);
  let config: AppConfig;
  try {
    config = await loadConfig(timeout);
  } catch (error) {
    reportBootstrapFailure(error);
    config = SAFE_CONFIG;
  }
  const services = createServices(config);
  await services.auth.restoreSession();
  return services;
}

