export function LiveOrderPanel({ orderId }: { orderId: string }) {
  const [events, setEvents] = useState<OrderEvent[]>([]);

  useEffect(() => {
    const controller = new AbortController();
    const subscription = orderStream.subscribe(orderId, (event) => {
      setEvents((current) => [...current.slice(-499), event]);
    });

    window.addEventListener('online', handleReconnect, {
      signal: controller.signal,
    });

    const observer = new ResizeObserver(reportPanelSize);
    const element = document.querySelector(`[data-order-id="${orderId}"]`);
    if (element) observer.observe(element);

    return () => {
      controller.abort();
      observer.disconnect();
      subscription.unsubscribe();
    };
  }, [orderId]);

  return <OrderTimeline data-order-id={orderId} events={events} />;
}

