let activeGeneration = 0;
let activeController: AbortController | undefined;

const delay = (ms: number, signal: AbortSignal) =>
  new Promise<void>((resolve, reject) => {
    const timer = setTimeout(resolve, ms);
    signal.addEventListener('abort', () => {
      clearTimeout(timer);
      reject(signal.reason);
    }, { once: true });
  });

async function fetchWithRetry(url: string, signal: AbortSignal) {
  for (let attempt = 1; attempt <= 3; attempt += 1) {
    signal.throwIfAborted();
    try {
      const response = await fetch(url, { signal });
      if (response.ok || response.status < 500 || attempt === 3) return response;
    } catch (error) {
      if (signal.aborted || attempt === 3) throw error;
    }
    const backoff = 200 * 2 ** (attempt - 1);
    await delay(backoff + Math.random() * backoff * 0.3, signal);
  }
  throw new Error('Unreachable');
}

export async function searchLatest(query: string) {
  activeController?.abort(new DOMException('Superseded', 'AbortError'));
  const controller = new AbortController();
  activeController = controller;
  const generation = ++activeGeneration;
  const signal = AbortSignal.any([controller.signal, AbortSignal.timeout(8_000)]);

  try {
    const response = await fetchWithRetry(`/api/search?q=${encodeURIComponent(query)}`, signal);
    if (!response.ok) throw new Error(`Search failed: ${response.status}`);
    const result = await response.json();
    if (generation !== activeGeneration || signal.aborted) return;
    searchStore.commit(result);
  } catch (error) {
    if (!signal.aborted) searchStore.fail(error);
  } finally {
    if (activeController === controller) activeController = undefined;
  }
}

const proxyCache = new WeakMap<object, object>();

export function observableMap<K, V>(raw: Map<K, V>): Map<K, V> {
  const cached = proxyCache.get(raw);
  if (cached) return cached as Map<K, V>;

  const proxy = new Proxy(raw, {
    get(target, key) {
      if (key === 'set') {
        return (mapKey: K, value: V) => {
          const previous = target.get(mapKey);
          target.set(mapKey, value);
          if (!Object.is(previous, value)) notify(target, mapKey);
          return proxy;
        };
      }
      if (key === 'delete') {
        return (mapKey: K) => {
          const deleted = target.delete(mapKey);
          if (deleted) notify(target, mapKey);
          return deleted;
        };
      }
      const value = Reflect.get(target, key, target);
      return typeof value === 'function' ? value.bind(target) : value;
    },
  });

  proxyCache.set(raw, proxy);
  return proxy;
}

